import { courseRepository } from './course-data';

export async function initCourseDetail(): Promise<void> {
  const badgesEl = document.querySelector<HTMLElement>('#course-badges');
  if (!badgesEl) return;
  const code = badgesEl.dataset.courseCode;
  const courses = await courseRepository.getCourses();
  const course = courses.find((item) => item.code === code);
  const tags = course?.tags || [];
  const tagsHtml = tags.map((tag) => `<span class="badge-tag">${tag}</span>`).join('');
  badgesEl.innerHTML = `<span class="badge-hashtag">#</span>${tagsHtml}`;
}
