import { courseRepository, type Course, type CourseLevel } from './course-data';

let courses: Course[] = [];
const list = document.querySelector<HTMLTableSectionElement>('#course-list');
const drawer = document.querySelector<HTMLElement>('#course-drawer');
const form = document.querySelector<HTMLFormElement>('#course-form');

async function saveCourses(): Promise<void> { await courseRepository.saveCourses(courses); }

function updateStats(): void {
  document.querySelector<HTMLElement>('#total-count')!.textContent = String(courses.length).padStart(2, '0');
  document.querySelector<HTMLElement>('#published-count')!.textContent = String(courses.filter((course) => course.published).length).padStart(2, '0');
  document.querySelector<HTMLElement>('#draft-count')!.textContent = String(courses.filter((course) => !course.published).length).padStart(2, '0');
}

function renderCourses(): void {
  if (!list) return;
  const query = document.querySelector<HTMLInputElement>('#course-search')!.value.toLowerCase();
  const category = document.querySelector<HTMLSelectElement>('#category-filter')!.value;
  const status = document.querySelector<HTMLSelectElement>('#status-filter')!.value;
  const filtered = courses.filter((course) => (!query || `${course.name} ${course.code}`.toLowerCase().includes(query)) && (category === 'all' || course.category === category) && (status === 'all' || (status === 'published' ? course.published : !course.published)));
  list.innerHTML = filtered.map((course) => `<tr><td><div class="course-name-cell"><img src="${course.image}" alt="" /><span><strong>${course.name}</strong><small>${course.code}</small></span></div></td><td>${course.category}</td><td>${course.level}</td><td>${course.duration}</td><td><button class="status-pill ${course.published ? 'is-published' : 'is-draft'}" data-action="toggle" data-id="${course.id}">${course.published ? 'Published' : 'Draft'}</button></td><td><div class="row-actions"><button type="button" data-action="edit" data-id="${course.id}">Edit</button><button type="button" data-action="delete" data-id="${course.id}">Delete</button></div></td></tr>`).join('');
  document.querySelector<HTMLElement>('#empty-state')!.hidden = filtered.length > 0;
  document.querySelector<HTMLElement>('#result-count')!.textContent = `Showing ${filtered.length} course${filtered.length === 1 ? '' : 's'}`;
  updateStats();
}

function openDrawer(course?: Course): void {
  if (!form || !drawer) return;
  form.reset();
  document.querySelector<HTMLElement>('#drawer-title')!.textContent = course ? 'Edit course' : 'Add a course';
  document.querySelector<HTMLInputElement>('#course-id')!.value = String(course?.id || '');
  document.querySelector<HTMLInputElement>('#course-name')!.value = course?.name || '';
  document.querySelector<HTMLInputElement>('#course-code')!.value = course?.code || '';
  document.querySelector<HTMLSelectElement>('#course-category')!.value = course?.category || 'Wine';
  document.querySelector<HTMLSelectElement>('#course-level')!.value = course?.level || 'Foundation';
  (['duration', 'price', 'description', 'image'] as const).forEach((key) => { document.querySelector<HTMLInputElement | HTMLTextAreaElement>(`#course-${key}`)!.value = course?.[key] || ''; });
  document.querySelector<HTMLInputElement>('#course-published')!.checked = course?.published || false;
  drawer.classList.add('is-open');
  drawer.setAttribute('aria-hidden', 'false');
}

function closeDrawer(): void { drawer?.classList.remove('is-open'); drawer?.setAttribute('aria-hidden', 'true'); }

function escapeCsv(value: unknown): string { return `"${String(value ?? '').replace(/"/g, '""')}"`; }

function exportCourses(): void {
  const format = document.querySelector<HTMLSelectElement>('#export-format')!.value;
  const headers: (keyof Course)[] = ['id', 'name', 'code', 'category', 'level', 'duration', 'price', 'description', 'image', 'published'];
  const csv = [headers, ...courses.map((course) => headers.map((header) => course[header]))].map((row) => row.map(escapeCsv).join(',')).join('\r\n');
  const content = format === 'csv' ? csv : JSON.stringify(courses, null, 2);
  const extension = format === 'csv' ? 'csv' : 'json';
  const blob = new Blob([content], { type: format === 'csv' ? 'text/csv;charset=utf-8' : 'application/json' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = `tbc-course-library.${extension}`;
  link.click();
  URL.revokeObjectURL(link.href);
}

export function initManagement(): void {
  document.addEventListener('click', async (event) => {
    const target = event.target as HTMLElement;
    const action = target.closest<HTMLElement>('[data-action]')?.dataset.action;
    const id = Number(target.closest<HTMLElement>('[data-id]')?.dataset.id);
    if (action === 'new') openDrawer();
    if (action === 'close') closeDrawer();
    if (action === 'edit') openDrawer(courses.find((course) => course.id === id));
    if (action === 'toggle') { const course = courses.find((item) => item.id === id); if (course) { course.published = !course.published; await saveCourses(); renderCourses(); } }
    if (action === 'delete' && window.confirm('Delete this course from the local library?')) { courses = courses.filter((course) => course.id !== id); await saveCourses(); renderCourses(); }
    if (action === 'export') exportCourses();
  });
  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const data = Object.fromEntries(new FormData(form).entries()) as Record<string, string>;
    const record: Course = { ...data, id: Number(document.querySelector<HTMLInputElement>('#course-id')!.value) || Date.now(), category: document.querySelector<HTMLSelectElement>('#course-category')!.value, level: document.querySelector<HTMLSelectElement>('#course-level')!.value as CourseLevel, published: document.querySelector<HTMLInputElement>('#course-published')!.checked } as Course;
    const index = courses.findIndex((course) => course.id === record.id);
    if (index === -1) courses.unshift(record); else courses[index] = record;
    await saveCourses(); renderCourses(); closeDrawer();
  });
  ['#course-search', '#category-filter', '#status-filter'].forEach((selector) => document.querySelector(selector)?.addEventListener('input', renderCourses));
  void courseRepository.getCourses().then((loadedCourses) => { courses = loadedCourses; renderCourses(); });
}
